UPDATE cumulation_table SET cumulation_table_name = 'OBD_COMPLETE_MIS_CUMULATIVE', evr_table_name= '<OBD_DBSCHEMA>.OBD_EVR_DETAILS', cumulation_columns='TOT_DURATION,TOT_CNT', evr_table_type='D', db_user='<DB_USERNAME>', db_pswd='<DB_PASSWORD>', db_ip='<DB_IP>', db_name='<DB_NAME>', db_srv='<OBD_DBSCHEMA>', select_query='SELECT DATE_TRUNC(''hour'', a.GEN_TIME) AS GEN_TIME, b.CLIENT_ID AS CLIENT_ID, a.CAMP_ID, a.EVR_EVENT, a.EVR_CAUSE, a.EVR_REASON,a.DURATION AS TOT_DURATION, COUNT(*) AS TOT_CNT FROM <:EVR_TABLE> a, <OBD_DBSCHEMA>.obd_campaign_mast b WHERE a.gen_time BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') AND a.CAMP_ID = b.camp_id GROUP BY DATE_TRUNC(''hour'', a.GEN_TIME), b.client_id, a.CAMP_ID, a.EVR_EVENT,a.EVR_CAUSE,a.EVR_REASON,a.DURATION' WHERE table_id = 3 ;

COMMIT;
